import { CommonModule, DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostListener,
  Inject,
  Renderer2,
  signal,
} from '@angular/core';

interface NavigationItem {
  label: string;
  target: string;
}

interface SolutionCard {
  eyebrow: string;
  title: string;
  description: string;
  headline: string;
  promise: string;
  result: string;
  image: string;
  voiceCommand: string;
  price: string;
  products: string[];
  outcomes: string[];
  featuredProducts?: ComboFeaturedProduct[];
}

interface ComboFeaturedProduct {
  label: string;
  description: string;
  image: string;
  x: number;
  y: number;
}

interface PromoProduct {
  quantity: string;
  name: string;
  image: string;
}

interface Benefit {
  icon: string;
  title: string;
  description: string;
}

@Component({
  selector: 'app-landing',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './landing.component.html',
  styleUrl: './landing.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LandingComponent {
  protected readonly isScrolled = signal(false);
  protected readonly isMenuOpen = signal(false);
  protected readonly activeSolutionIndex = signal(0);

  private readonly whatsappPhone = '5493512517479';

  protected readonly whatsappUrl = this.createWhatsappUrl(
    'Hola ModoConectado, quiero recibir información para automatizar mi espacio.',
  );

  protected readonly navItems: NavigationItem[] = [
    { label: 'Inicio', target: 'inicio' },
